def knowledge_exclusions_for_source(self, source_id: str) -> List[str]:
    """Return the durable secrecy boundary attached to a source record."""
    source = str(source_id or "")
    row = self.conn.execute(
        "SELECT excluded_names FROM character_knowledge_events WHERE source_id=? "
        "ORDER BY id LIMIT 1", (source,)
    ).fetchone()
    if row is not None:
        try:
            return [str(name) for name in json.loads(row["excluded_names"] or "[]")]
        except (TypeError, ValueError):
            return []
    # #883 CR R1 S2: bare ``secret_order:`` shared *sources* are no longer
    # produced (create/update → private briefs; production disclosure →
    # ``secret_order_disclosure:``; register gate rejects the prefix).
    # Retained: ``record_public_knowledge_event`` still inherits exclusions
    # by looking up secret_orders when source_id is ``secret_order:N`` —
    # exercised by AC harness paths (test_character_knowledge_489 /
    # test_minister_context / test_web_chat_serialization_393). Without
    # this branch those writes lose the blacklist. session.py only DELETEs
    # legacy sources with this prefix; no live production producer.
    match = re.fullmatch(r"secret_order(?:_brief)?:(\d+)", source)
    if match:
        order_id = int(match.group(1))
        order = self.conn.execute(
            "SELECT excluded_names FROM secret_orders WHERE id=?", (order_id,)
        ).fetchone()
        if order is not None:
            try:
                return [str(name) for name in json.loads(order["excluded_names"] or "[]")]
            except (TypeError, ValueError):
                return []
    # #1829 reopen：公开说法排除名单与正文同表，按 public_saying:<id> 回查。
    match = re.fullmatch(r"public_saying:(\d+)", source)
    if match:
        saying = self.conn.execute(
            "SELECT excluded_names FROM public_sayings WHERE id=?",
            (int(match.group(1)),),
        ).fetchone()
        if saying is not None:
            try:
                return [str(name) for name in json.loads(saying["excluded_names"] or "[]")]
            except (TypeError, ValueError):
                return []
        return []
    row = self.conn.execute(
        "SELECT excluded_names FROM character_knowledge_sources WHERE source_id=?", (source,)
    ).fetchone()
    if row is not None:
        try:
            return [str(name) for name in json.loads(row["excluded_names"] or "[]")]
        except (TypeError, ValueError):
            return []
    return []

def classify_execution_coverage(
    action_type: object, payload: Optional[Mapping[str, object]] = None,
) -> Optional[str]:
    """只读 canonical 动作及结构化细类判别执行覆盖域，不解析旨文。"""
    action = str(action_type or "").strip()
    if action in _COVERAGE_APPOINTMENT:
        return "appointment"
    if action in _COVERAGE_MULTI_MONTH:
        return "multi_month"
    if action == "punishment":
        from ming_sim.action_clusters import cluster_by_kind

        punish_action = str((payload or {}).get("punish_action") or "").strip()
        cluster = cluster_by_kind("punishment")
        field = next((f for f in cluster.fields if f.name == "punish_action"), None) if cluster else None
        if field is not None and field.execution_coverage is not None:
            return field.execution_coverage.get(punish_action)
    return None

def _strategic_result_item_has_material_world_state(item: Dict[str, object]) -> bool:
    if item.get("rejected"):
        return False
    if item.get("created"):
        return True
    for old_key, new_key in (
        ("old", "new"),
        ("old_status", "status"),
        ("old_office", "new_office"),
        ("old_office_type", "office_type"),
        ("old_loyalty", "new_loyalty"),
        ("old_power", "new_power"),
        ("old_style", "new_style"),
    ):
        if old_key in item and new_key in item and str(item.get(old_key)) != str(item.get(new_key)):
            return True
    action = str(item.get("动作") or item.get("action") or "").strip()
    if action in {"处置", "罢黜"} and item.get("status"):
        return True
    if action in {"任命", "调任"} and (
        item.get("new_office") or item.get("office")
    ):
        return True
    if action == "易主" and item.get("new_power"):
        return True
    if "delta" in item:
        delta = item.get("delta")
        if delta is None:
            return False
        try:
            return int(delta) != 0
        except (TypeError, ValueError):
            return bool(delta)
    return False

