    """
    base_entries = _roster_dict_entries(baseline_roster)
    corr_entries = _roster_dict_entries(correction_roster)
    if not base_entries:
        return []
    # corr 短于 baseline：仅当被截去的尾槽全是机构/空才可（人物槽缺失 → 不明）
