def classify_transport_failure(error: BaseException) -> ClassifiedFailure:
    """先分类后重试。只认 typed 信号；不从错误散文猜语义（ADR 0142）。

    可重试：瞬断/空转/5xx/408/429/空输出；召对 429 例外在调用策略落实。
    不可重试：其余确定性 4xx（#1452 Unknown model 等带 4xx status）。
    未知（无 status 的笼统 stream/run error）→ 不洗成瞬断，立即上浮。

    本函数是 APITimeout/Connection/Status/空输出/RunError → code/retryable/status 的唯一权威
    （llm_unavailable_from_error / run_error_event_failure / empty_output_failure 委派或同构）。
    """
    if isinstance(error, TransportIdleTimeout):
        return ClassifiedFailure(
            retryable=True,
            code="llm_idle_timeout",
            status_code=None,
            provider_message=str(error) or "idle timeout",
            message="LLM 调用空转超时。",
        )
    if isinstance(error, APITimeoutError):
        return ClassifiedFailure(
            retryable=True,
            code="llm_timeout",
            status_code=None,
            provider_message=str(error),
            message="LLM 调用超时。",
        )
    if isinstance(error, APIConnectionError):
        return ClassifiedFailure(
            retryable=True,
            code="llm_connection_error",
            status_code=None,
            provider_message=str(error),
            message="LLM 连接失败。",
        )
    if isinstance(error, APIStatusError):
        status_i = _coerce_status(getattr(error, "status_code", None))
        code = f"llm_http_{status_i}" if status_i is not None else "llm_http_error"
        return ClassifiedFailure(
            retryable=_status_retryable(status_i),
            code=code,
            status_code=status_i,
            provider_message=str(error),
            message=f"LLM 调用失败（HTTP {status_i}）。" if status_i else "LLM 调用失败。",
        )
    if isinstance(error, LLMUnavailable):
        status = error.status_code
        code = str(error.code or "llm_unavailable")
        pmsg = str(error.provider_message or error.message or "")
        status_i = _coerce_status(status)
        if status_i is not None:
            return ClassifiedFailure(
                retryable=_status_retryable(status_i),
                code=code,
                status_code=status_i,
                provider_message=pmsg,
                message=str(error.message or pmsg or "LLM 调用失败。"),
            )
        if code in {
            "llm_timeout",
            "llm_connection_error",
            "llm_idle_timeout",
            "llm_empty_output",
        }:
            return ClassifiedFailure(
                retryable=True,
                code=code,
                status_code=None,
                provider_message=pmsg,
                message=str(error.message or pmsg or "LLM 调用失败。"),
            )
        if code.startswith("llm_http_"):
            tail = code[len("llm_http_") :]
            status_from_code = _coerce_status(tail)
            if status_from_code is not None:
                return ClassifiedFailure(
                    retryable=_status_retryable(status_from_code),
                    code=code,
                    status_code=status_from_code,
                    provider_message=pmsg,
                    message=str(error.message or pmsg or "LLM 调用失败。"),
                )

def _pin_world_question_event_bindings(
    chain: Dict[str, Any], *, db: Any, state: Any, turn: int,
) -> None:
    """推送案头时把事件身份钉进月链（ADR 0115）。

    案头行身份保持 ``world-question:{turn}:{idx}``，后续问题顺延 idx，不把事件 id 写进那一列。
    事件身份只来自交接时请旨块自带、且属于当回合
    ``gather_fiscal_levy_petitions`` 快照的 event_id。只从 origin_ref 填进来的
    id 不是这份快照。没有这份身份的请旨保持非事件身份：剩余数量不能证明它属于
    某一到期事项，也不按标题猜配。钉完之后快照再变也不改这张表。
    """
    if isinstance(chain.get("world_question_event_bindings"), dict):
        return
    from ming_sim.issues import gather_fiscal_levy_petitions

    questions = [
        q for q in (chain.get("world_questions") or []) if isinstance(q, dict)
    ]
    due_set: set[str] = set()
    for ev in gather_fiscal_levy_petitions(state, db):
        event_id = str(ev.id or "").strip()
        if event_id:
            due_set.add(event_id)
    bindings: Dict[str, str] = {}
    used: set[str] = set()
    for idx, question in enumerate(questions):
        desk_key = f"{_WORLD_QUESTION_PREFIX}{turn}:{int(chain.get('world_question_offset', 0)) + idx}"
        echoed = str(question.get("event_id") or "").strip()
        origin_ref = str(question.get("origin_ref") or "").strip()
        if origin_ref and echoed == origin_ref:
            echoed = ""
        if echoed in due_set and echoed not in used:
            bindings[desk_key] = echoed
            used.add(echoed)
    chain["world_question_event_bindings"] = bindings

